def counter(n):
    i = 0
    while i < n:
        yield i
        i += 1
print([x for x in counter(4)])
for v in counter(3):
    print('v', v)

def pairs():
    yield 1, 2
    yield 3, 4
print(list(pairs()))
for a, b in pairs():
    print(a + b)

def repeat(v, n):
    i = 0
    while i < n:
        yield v
        i += 1
print(list(repeat('x', 3)))

def counter(n):
    i = 0
    while i < n:
        yield i
        i += 1
def double(src):
    for v in src:
        yield v * 2
print(list(double(counter(4))))

def evens(n):
    for i in range(n):
        if i % 2 == 0:
            yield i
print(list(evens(7)))
